        let h2 = hash_file(&paths[0]).unwrap();
        assert_eq!(h1, h2, "同一文件两次哈希必须相同");
        assert_ne!(h1, hash_file(&paths[1]).unwrap(), "不同文件哈希应不同");
        fs::remove_dir_all(&dir).unwrap();
    }

    #[test]
    fn empty_file_hashes_without_error() {
        let dir = tmp_dir("empty");
        let _ = fs::remove_dir_all(&dir);
        fs::create_dir_all(&dir).unwrap();
        let empty = dir.join("empty.bin");
        fs::write(&empty, []).unwrap();
        assert!(hash_file(&empty).is_ok());
        fs::remove_dir_all(&dir).unwrap();
    }

    #[test]
    fn single_and_multi_thread_agree() {
        let dir = tmp_dir("agree");
        let _ = fs::remove_dir_all(&dir);
        let paths = make_test_files(&dir, 12, 8192).unwrap();
        let mut single = hash_single_thread(&paths).unwrap();
        let mut multi = hash_multi_thread(&paths, 4).unwrap();
        single.sort();
        multi.sort();
        assert_eq!(single, multi);
        fs::remove_dir_all(&dir).unwrap();
    }

    #[test]
    fn more_workers_than_files_still_works() {
        let dir = tmp_dir("many-workers");
        let _ = fs::remove_dir_all(&dir);
        let paths = make_test_files(&dir, 2, 4096).unwrap();
        let mut out = hash_multi_thread(&paths, 8).unwrap();
        assert_eq!(out.len(), 2);
        out.sort();
        let mut single = hash_single_thread(&paths).unwrap();
        single.sort();
        assert_eq!(out, single);
        fs::remove_dir_all(&dir).unwrap();
    }

    #[test]
    fn missing_file_returns_error() {
        let missing = PathBuf::from("/tmp/rust-day20-no-such-file.bin");
        assert!(hash_file(&missing).is_err());
        let paths = vec![missing];
        assert!(hash_single_thread(&paths).is_err());
    }
}

//! 第 21 天 · 第三周复盘验收：Box、Rc、Arc、Mutex、channel 一次串起来。
//!
//! 三种共享方式算同一个总数：单线程 Rc<RefCell>、多线程 Arc<Mutex>、
//! channel 聚合。结果必须一致——共享的姿势不同，答案不能不同。

use std::cell::RefCell;
use std::rc::Rc;
use std::sync::{Arc, Mutex, mpsc};
use std::thread;

/// 递归类型必须用 Box：没有它，枚举的大小是无限的，编译器算不出 `Expr` 占多少字节。
#[derive(Debug)]
enum Expr {
    Num(i64),
    Add(Box<Expr>, Box<Expr>),
    Mul(Box<Expr>, Box<Expr>),
}

fn eval(e: &Expr) -> i64 {
    match e {
        Expr::Num(n) => *n,
        Expr::Add(a, b) => eval(a) + eval(b),
        Expr::Mul(a, b) => eval(a) * eval(b),
    }
}

/// 单线程共享计数：Rc 管「多方共享所有权」，RefCell 管「内部可变性」。
/// 每个闭包 clone 一份 Rc，改数时 `borrow_mut()` 在运行期做借用检查。
fn single_thread_total(n_workers: usize, per_worker: usize) -> usize {
    let total = Rc::new(RefCell::new(0_usize));
    let mut jobs = Vec::new();
    for _ in 0..n_workers {
        let t = Rc::clone(&total);
        jobs.push(move || {
            for _ in 0..per_worker {
                *t.borrow_mut() += 1;
            }
        });
    }
    for job in jobs {
        job();
    }
    *total.borrow()
}

/// 多线程共享计数：Arc 管「跨线程共享所有权」，Mutex 管「跨线程互斥」。
/// 每个线程先在本地累加，攒够了再一次性上锁合并——锁只拿一次，
/// 而不是每加 1 就抢一次锁。锁的持有范围越小，线程之间等得越少。
fn multi_thread_total(n_workers: usize, per_worker: usize) -> usize {
    let total = Arc::new(Mutex::new(0_usize));
    let mut handles = Vec::new();
    for _ in 0..n_workers {
        let t = Arc::clone(&total);
        handles.push(thread::spawn(move || {
            let mut local = 0_usize;
            for _ in 0..per_worker {
                local += 1;
            }
            *t.lock().unwrap() += local;
        }));
    }
    for h in handles {
        h.join().unwrap();
    }
    *total.lock().unwrap()
}

/// 消息传递版：worker 之间不共享任何可变状态，各算各的，
/// 算完把部分和发回主线程聚合。主线程 `drop(tx)` 后，
/// `rx.iter()` 在收到全部部分和、channel 关闭时自然结束。
fn channel_total(n_workers: usize, per_worker: usize) -> usize {
    let (tx, rx) = mpsc::channel::<usize>();
    let mut handles = Vec::new();
    for _ in 0..n_workers {
        let tx = tx.clone();
        handles.push(thread::spawn(move || {
            tx.send(per_worker).unwrap();
        }));
    }
    drop(tx);
    let total: usize = rx.iter().sum();
    for h in handles {
        h.join().unwrap();
    }
    total
}

fn main() {
    let expr = Expr::Add(
        Box::new(Expr::Num(2)),
        Box::new(Expr::Mul(Box::new(Expr::Num(3)), Box::new(Expr::Num(4)))),
    );
    println!("2 + 3 * 4 = {}", eval(&expr));

    let n_workers = 4;
    let per_worker = 1000;
    let single = single_thread_total(n_workers, per_worker);
    let multi = multi_thread_total(n_workers, per_worker);
    let channeled = channel_total(n_workers, per_worker);
    println!("单线程 Rc<RefCell>：{single}");
    println!("多线程 Arc<Mutex>：{multi}");
    println!("channel 聚合：{channeled}");
    assert_eq!(single, multi);
    assert_eq!(multi, channeled);
    println!("三种共享方式结果一致：{single}（{n_workers} 个 worker × 每人 {per_worker} 次）");
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn eval_arithmetic() {
        let expr = Expr::Add(
            Box::new(Expr::Num(2)),
            Box::new(Expr::Mul(Box::new(Expr::Num(3)), Box::new(Expr::Num(4)))),
        );
        assert_eq!(eval(&expr), 14);
    }

    #[test]
    fn three_sharing_styles_agree() {
        assert_eq!(single_thread_total(4, 100), 400);
        assert_eq!(multi_thread_total(4, 100), 400);
        assert_eq!(channel_total(4, 100), 400);
    }

    #[test]
    fn rc_clones_share_one_counter() {
        let total = Rc::new(RefCell::new(0_usize));
        let a = Rc::clone(&total);
        let b = Rc::clone(&total);
        *a.borrow_mut() += 1;
        *b.borrow_mut() += 1;
        assert_eq!(*total.borrow(), 2);
        assert_eq!(Rc::strong_count(&total), 3);
    }

    #[test]
    fn one_worker_still_works() {
        assert_eq!(multi_thread_total(1, 50), 50);
        assert_eq!(channel_total(1, 50), 50);
    }
}

//! 第 22 天示例：loglib —— 一个可复用的日志解析库 crate。
//!
//! 对照 C++：一个 crate 相当于一个静态/动态库 + 它的公开头文件；
//! `pub` 标记的项就是头文件里声明的符号，没标记 `pub` 的是 .c 文件
//! 里的 static 函数——外部看不见，也链接不到。

pub mod parse;
pub mod stats;

// 只导出最常用的两个名字，调用方写 `loglib::count_levels` 就够了，
// 不必记住它住在哪个模块里。这就是 re-export（重新导出）的用途。
pub use parse::parse_level;
pub use stats::count_levels;

//! 解析一行日志，取出它的级别。

/// 日志级别。对照 C++：就是一个 enum class，只不过 Rust 的变体
/// 可以携带数据（这里没带，纯粹是标签）。
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Level {
    Info,
    Warn,
    Error,
    Debug,
    Unknown,
}

impl Level {
    /// 从字符串解析级别；不认识的返回 Unknown 而不是报错——
    /// 日志解析是"脏数据"场景，宁可降级也不要让整个程序崩掉。
    pub fn from_label(s: &str) -> Level {
        match s {
            "INFO" => Level::Info,
            "WARN" => Level::Warn,
            "ERROR" => Level::Error,
            "DEBUG" => Level::Debug,
            _ => Level::Unknown,
        }
    }
}

/// 从一行日志里取出级别。日志格式约定为 `[LEVEL] 消息`，
/// 形如 `[ERROR] disk full`。格式不对返回 None。
pub fn parse_level(line: &str) -> Option<Level> {
    let line = line.trim();
    let rest = line.strip_prefix('[')?;
    let (level, _) = rest.split_once(']')?;
    Some(Level::from_label(level))
}

/// 只在本 crate 内部用的小工具：没加 pub，外部 crate 看不见它。
/// 对照 C++：相当于 .c 文件里的 static 函数。
pub(crate) fn is_blank(line: &str) -> bool {
    line.trim().is_empty()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parses_known_levels() {
        assert_eq!(parse_level("[INFO] ok"), Some(Level::Info));
        assert_eq!(parse_level("[ERROR] boom"), Some(Level::Error));
    }

    #[test]
    fn malformed_lines_yield_none() {
        assert_eq!(parse_level("no brackets here"), None);
        assert_eq!(parse_level("[INFO]"), Some(Level::Info));
        assert_eq!(parse_level(""), None);
    }

    #[test]
    fn unknown_level_is_not_an_error() {
        assert_eq!(parse_level("[TRACE] x"), Some(Level::Unknown));
    }
}

//! 按级别统计日志行数。

use crate::parse::{is_blank, parse_level, Level};
use std::collections::HashMap;

/// 统计一段日志文本里各级别的行数。空行跳过，格式不对的行
/// 计入 Unknown——这是"脏数据降级"策略在统计层的体现。
pub fn count_levels(text: &str) -> HashMap<Level, usize> {
    let mut counts = HashMap::new();
    for line in text.lines() {
        if is_blank(line) {
            continue;
        }
        let level = parse_level(line).unwrap_or(Level::Unknown);
        *counts.entry(level).or_insert(0) += 1;
    }
    counts
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn counts_each_level() {
        let text = "[INFO] a\n[INFO] b\n[ERROR] c\n\n[WARN] d\njunk line\n";
        let counts = count_levels(text);
        assert_eq!(counts[&Level::Info], 2);
        assert_eq!(counts[&Level::Error], 1);
        assert_eq!(counts[&Level::Warn], 1);
        assert_eq!(counts[&Level::Unknown], 1);
    }

    #[test]
    fn empty_text_gives_empty_map() {
        assert!(count_levels("").is_empty());
        assert!(count_levels("\n\n").is_empty());
    }
}

//! 第 22 天示例：logcount —— workspace 里的一个二进制 crate。
//!
//! 它只负责"读文件 + 打印结果"，解析与统计的逻辑全在 loglib 里。
//! 对照 C++：这相当于一个 main.c 只做命令行处理，真正的逻辑
//! 在 liblog.a 里；改库不需要重新理解 main，改 main 不用碰库。

use loglib::count_levels;
use std::env;
use std::fs;
use std::process::ExitCode;

fn main() -> ExitCode {
    let path = match env::args().nth(1) {
        Some(p) => p,
        None => {
            eprintln!("用法：logcount <日志文件路径>");
            return ExitCode::from(2);
        }
    };
    let text = match fs::read_to_string(&path) {
        Ok(t) => t,
        Err(e) => {
            eprintln!("读文件 {path} 失败：{e}");
            return ExitCode::from(1);
        }
    };
    let mut counts: Vec<_> = count_levels(&text).into_iter().collect();
    counts.sort_by_key(|(level, _)| format!("{level:?}"));
    for (level, n) in counts {
        println!("{level:?}: {n}");
    }
    ExitCode::SUCCESS
}

//! 第 23 天示例：textutil —— 文本小工具库，专门用来练测试。
//!
//! 对照 C++：`cargo test` 相当于把 GoogleTest 的"写测试 + 编译测试
//! 二进制 + 跑"三步合成一步；`#[cfg(test)]` 的测试模块只在测试
//! 构建时编译，不会进发布产物。

/// 统计一段文本里的单词数。单词以空白分隔，空文本返回 0。
///
/// # 示例
///
/// ```
/// assert_eq!(textutil::word_count("hello rust world"), 3);
/// assert_eq!(textutil::word_count(""), 0);
/// ```
pub fn word_count(text: &str) -> usize {
    text.split_whitespace().count()
}

/// 把连续空白压缩成单个空格，并去掉首尾空白。
pub fn normalize_space(text: &str) -> String {
    text.split_whitespace().collect::<Vec<_>>().join(" ")
}

/// 取出第一个单词；空文本会 panic（调用方应先检查再调它）。
pub fn first_word(text: &str) -> &str {
    text.split_whitespace()
        .next()
        .expect("empty text has no first word")
}

/// 判断一个字符串是不是回文（忽略大小写与非字母数字字符）。
/// 空字符串按回文算（与 C++ 里常见的"空串是回文"约定一致）。
pub fn is_palindrome(text: &str) -> bool {
    let cleaned: Vec<char> = text
        .chars()
        .filter(|c| c.is_alphanumeric())
        .map(|c| c.to_ascii_lowercase())
        .collect();
    cleaned.iter().eq(cleaned.iter().rev())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn counts_words() {
        assert_eq!(word_count("hello rust world"), 3);
        assert_eq!(word_count("  one   two  "), 2);
        assert_eq!(word_count(""), 0);
    }

    #[test]
    fn normalizes_whitespace() {
        assert_eq!(normalize_space("  a   b\tc\n"), "a b c");
        assert_eq!(normalize_space(""), "");
    }

    #[test]
    fn first_word_works() {
        assert_eq!(first_word("  hello world"), "hello");
    }

    #[test]
    #[should_panic(expected = "empty text")]
    fn first_word_panics_message() {
        first_word("   ");
    }

    #[test]
    fn palindrome_examples() {
        assert!(is_palindrome("A man, a plan, a canal: Panama"));
        assert!(is_palindrome("racecar"));
        assert!(!is_palindrome("hello"));
        assert!(is_palindrome(""));
    }

    #[test]
    fn word_count_handles_unicode() {
        assert_eq!(word_count("你好 世界"), 2);
    }
}

