//! 第 24 天示例：benchlab —— 用 criterion 给两种写法计时。
//!
//! 对照 C++：criterion 相当于 Google Benchmark；`cargo bench` 是
//! 它的统一入口。内置 `#[bench]` 需要 nightly，所以稳定版用 criterion。

/// 用 `split_whitespace` 数单词（第 23 天 textutil 的写法）。
pub fn count_words_split(text: &str) -> usize {
    text.split_whitespace().count()
}

/// 手写扫描数单词：逐字符走，遇到"空白后跟非空白"时计数加一。
pub fn count_words_manual(text: &str) -> usize {
    let mut count = 0;
    let mut in_word = false;
    for c in text.chars() {
        if c.is_whitespace() {
            in_word = false;
        } else if !in_word {
            in_word = true;
            count += 1;
        }
    }
    count
}

/// 用 `collect::<Vec<_>>().join(" ")` 压缩空白（第 23 天的写法）。
pub fn normalize_collect(text: &str) -> String {
    text.split_whitespace().collect::<Vec<_>>().join(" ")
}

/// 手写压缩空白：直接往一个 String 里 push，避免中间 Vec。
pub fn normalize_push(text: &str) -> String {
    let mut out = String::with_capacity(text.len());
    let mut need_space = false;
    for word in text.split_whitespace() {
        if need_space {
            out.push(' ');
        }
        out.push_str(word);
        need_space = true;
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn both_word_counters_agree() {
        let cases = ["", "hello rust world", "  one   two\tthree\n", "你好 世界"];
        for text in cases {
            assert_eq!(count_words_split(text), count_words_manual(text));
        }
    }

    #[test]
    fn both_normalizers_agree() {
        let cases = ["", "  a   b\tc\n", "hello rust"];
        for text in cases {
            assert_eq!(normalize_collect(text), normalize_push(text));
        }
    }
}

//! criterion 基准：两种数单词写法、两种压缩空白写法，同场对比。
//! 每次跑都会在终端输出中位数耗时，并在 target/criterion/ 下存 HTML 报告。

use benchlab::{count_words_manual, count_words_split, normalize_collect, normalize_push};
use criterion::{black_box, criterion_group, criterion_main, Criterion};

fn bench_word_count(c: &mut Criterion) {
    // 一段约 4KB 的固定输入：100 遍重复的句子，避免输入太小导致计时失真。
    let text = "hello rust world, benchmarking is how you stop guessing. ".repeat(100);

    let mut group = c.benchmark_group("word_count");
    group.bench_function("split", |b| b.iter(|| count_words_split(black_box(&text))));
    group.bench_function("manual", |b| {
        b.iter(|| count_words_manual(black_box(&text)))
    });
    group.finish();
}

fn bench_normalize(c: &mut Criterion) {
    let text =
        "  hello   rust   world,   benchmarking   is   how   you   stop   guessing. ".repeat(100);

    let mut group = c.benchmark_group("normalize_space");
    group.bench_function("collect_join", |b| {
        b.iter(|| normalize_collect(black_box(&text)))
    });
    group.bench_function("push_str", |b| b.iter(|| normalize_push(black_box(&text))));
    group.finish();
}

criterion_group!(benches, bench_word_count, bench_normalize);
criterion_main!(benches);

//! 手写计时对照组：用 `Instant` 自己量，跑 5 遍看数值抖动有多大。
//! 跑法：`cargo run --release --bin manual_timing`

use benchlab::{count_words_manual, count_words_split};
use std::time::Instant;

fn main() {
    let text = "hello rust world, benchmarking is how you stop guessing. ".repeat(100);

    for (name, f) in [
        ("split", count_words_split as fn(&str) -> usize),
        ("manual", count_words_manual as fn(&str) -> usize),
    ] {
        print!("{name:>7}: ");
        for _ in 0..5 {
            let start = Instant::now();
            for _ in 0..1000 {
                // 黑盒：防止编译器把"结果没人用"的调用整个优化掉。
                std::hint::black_box(f(&text));
            }
            print!("{:>6.2} ms  ", start.elapsed().as_secs_f64() * 1000.0);
        }
        println!();
    }
    println!("同一段代码，5 遍结果都不一样——这就是手写计时需要被替代的原因。");
}

//! 第 25 天示例：featlab —— features、profile 与 Cargo.lock 的三合一实验台。
//!
//! 跑法：
//!   cargo run                         （默认特性 fast，dev profile）
//!   cargo run --no-default-features   （关掉 fast，看 itoa 依赖消失）
//!   cargo run --features verbose      （再开 verbose）
//!   cargo run --release               （release profile：溢出静默回绕）
//!   cargo tree                        （看 itoa 在不在依赖树里）

/// 用 itoa 格式化（fast 特性开时）；否则退回标准库的 to_string。
fn format_number(n: i64) -> String {
    #[cfg(feature = "fast")]
    {
        let mut buf = itoa::Buffer::new();
        buf.format(n).to_owned()
    }
    #[cfg(not(feature = "fast"))]
    {
        n.to_string()
    }
}

/// 200 + 100 在 u8 里会溢出。dev 下 overflow-checks 打开会 panic，
/// release 下默认关闭，会静默回绕成 44。用 catch_unwind 把两种
/// 行为都变成可打印的结果，而不是让程序直接崩掉。
fn add_with_overflow_report(a: u8, b: u8) -> String {
    std::panic::set_hook(Box::new(|_| {})); // 压住 panic 的默认报错输出
    match std::panic::catch_unwind(|| a + b) {
        Ok(v) => format!("{a} + {b} = {v}（release 下静默回绕）"),
        Err(_) => format!("{a} + {b}：溢出被捕获（dev 下 overflow-checks 开启）"),
    }
}

fn main() {
    println!(
        "特性 fast：{}",
        if cfg!(feature = "fast") { "开" } else { "关" }
    );
    println!(
        "特性 verbose：{}",
        if cfg!(feature = "verbose") {
            "开"
        } else {
            "关"
        }
    );
    #[cfg(feature = "verbose")]
    println!("verbose：正在格式化数字 1234567……");
    let n = 1_234_567_i64;
    let via = if cfg!(feature = "fast") {
        "itoa"
    } else {
        "to_string"
    };
    println!("格式化 {n} -> {}（{via}）", format_number(n));
    println!("{}", add_with_overflow_report(200, 100));
    debug_assert_eq!(format_number(42), "42"); // 只在 dev（含 debug-assertions）下执行
    println!("debug_assertions：{}", cfg!(debug_assertions));
}

//! doclab：演示文档注释（`///` / `//!`）与 rustdoc 的微型库。
//!
//! 本文件演示三件事：
//! 1. 文档注释怎么写才算"一份能看的文档"；
//! 2. `# Examples` 里的代码示例会被 `cargo test` 真正编译运行（doctest）；
//! 3. intra-doc 链接（见 [`RetryPolicy`]）与 `cargo doc` 的生成结果。
//!
//! 快速试用：
//! ```
//! let bytes = doclab::parse_size("1K").unwrap();
//! assert_eq!(bytes, 1024);
//! ```

use std::fmt;

/// 解析人类可读的大小字符串，如 `"512"`、`"1K"`、`"2M"`。
///
/// 支持的后缀只有 `K`、`M`、`G`（1024 进制），不区分大小写；
/// 不带后缀时按字节数理解。字符串两端允许空白。
///
/// # Examples
///
/// ```
/// assert_eq!(doclab::parse_size("512").unwrap(), 512);
/// assert_eq!(doclab::parse_size("1K").unwrap(), 1024);
/// assert_eq!(doclab::parse_size("2m").unwrap(), 2 * 1024 * 1024);
/// ```
///
/// # Errors
///
/// 字符串为空、数字部分解析失败、或后缀不在 `K` / `M` / `G` 中时，
/// 返回 [`ParseSizeError`]。
pub fn parse_size(s: &str) -> Result<u64, ParseSizeError> {
    let s = s.trim();
    if s.is_empty() {
        return Err(ParseSizeError::Empty);
    }
    let (num_part, mult) = match s.chars().last() {
        Some(c) if c.is_ascii_alphabetic() => {
            let m = match c.to_ascii_uppercase() {
                'K' => 1024_u64,
                'M' => 1024_u64 * 1024,
                'G' => 1024_u64 * 1024 * 1024,
                _ => return Err(ParseSizeError::BadSuffix(c)),
            };
            (&s[..s.len() - 1], m)
        }
        _ => (s, 1),
    };
    let n: u64 = num_part
        .trim()
        .parse()
        .map_err(|_| ParseSizeError::BadNumber(num_part.to_owned()))?;
    n.checked_mul(mult).ok_or(ParseSizeError::Overflow)
}

/// `parse_size` 失败时的错误类型。
///
/// 用独立的错误枚举而不是 `String`，调用方才能用 `match` 区分
/// "空串""数字错""后缀错"三种情况——第 10 天讲过的原则：
/// 库返回结构化错误，应用才用 `anyhow` 兜底。
#[derive(Debug, PartialEq, Eq)]
pub enum ParseSizeError {
    /// 输入是空串（或只有空白）。
    Empty,
    /// 数字部分解析失败，携带原始数字文本。
    BadNumber(String),
    /// 后缀不在 `K` / `M` / `G` 中，携带原始后缀字符。
    BadSuffix(char),
    /// 数值乘上倍数后超出 `u64`。
    Overflow,
}

impl fmt::Display for ParseSizeError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ParseSizeError::Empty => write!(f, "大小字符串为空"),
            ParseSizeError::BadNumber(s) => write!(f, "数字部分无法解析：{s}"),
            ParseSizeError::BadSuffix(c) => write!(f, "不支持的大小后缀：{c}"),
            ParseSizeError::Overflow => write!(f, "大小超出 u64 范围"),
        }
    }
}

impl std::error::Error for ParseSizeError {}

/// 指数退避的重试策略：失败后第 n 次重试前等待多久。
///
/// 延迟按 `base_ms * 2^n` 增长，但不超过 `max_ms`。
/// 典型用法是配合 [`parse_size`] 之类的解析结果做"读配置→重试拉取"的
/// 循环——第 5 周写反向代理时，这个结构会直接用上。
///
/// # Examples
///
/// ```
/// use doclab::RetryPolicy;
///
/// # let policy = RetryPolicy::new(100, 800);
/// assert_eq!(policy.delay_for(0).as_millis(), 100);
/// assert_eq!(policy.delay_for(1).as_millis(), 200);
/// assert_eq!(policy.delay_for(3).as_millis(), 800); // 800 封顶，不再翻倍
/// ```
pub struct RetryPolicy {
    base_ms: u64,
    max_ms: u64,
}

impl RetryPolicy {
    /// 新建一个重试策略。
    ///
    /// # Panics
    ///
    /// `base_ms` 为 0 或 `max_ms` 小于 `base_ms` 时 panic：
    /// 零延迟的重试等于忙循环，调用方应在构造时就发现这个错误。
    pub fn new(base_ms: u64, max_ms: u64) -> Self {
        assert!(base_ms > 0, "base_ms 必须大于 0");
        assert!(max_ms >= base_ms, "max_ms 不能小于 base_ms");
        Self { base_ms, max_ms }
    }

    /// 第 `attempt` 次重试（从 0 开始计数）前应等待的时间。
    pub fn delay_for(&self, attempt: u32) -> std::time::Duration {
        let shift = attempt.min(10);
        let ms = self.base_ms.saturating_mul(1 << shift).min(self.max_ms);
        std::time::Duration::from_millis(ms)
    }
}

