//! hasher-core：项目 2 文件哈希器的核心库。
//!
//! 把"算哈希"从命令行程序里抽出来，变成一个可以被任何 bin crate
//! 依赖的库：哈希算法、任务分发、结果聚合都在这里，
//! `hasher-cli` 只负责解析命令行参数、打印结果与计时。
//!
//! 快速试用：
//! ```
//! use hasher_core::hash_file;
//!
//! let path = std::env::temp_dir()
//!     .join(format!("hasher-core-doctest-{}.txt", std::process::id()));
//! std::fs::write(&path, b"hello").unwrap();
//! assert!(hash_file(&path).is_ok());
//! let _ = std::fs::remove_file(&path);
//! ```

use std::collections::hash_map::DefaultHasher;
use std::fs;
use std::hash::{Hash, Hasher};
use std::io::{self, Read};
use std::path::{Path, PathBuf};
use std::sync::{mpsc, Arc, Mutex};
use std::thread;

/// 对单个文件算哈希：按 8 KiB 分块读，边读边喂给 [`DefaultHasher`]。
///
/// 分块读而不是 `fs::read` 整文件进内存——大文件也不会把内存撑爆。
/// 哈希是确定性的：同一文件两次调用返回相同的值，适合做单线程版与
/// 多线程版的结果比对。注意 [`DefaultHasher`] 是 SipHash，
/// 不是密码学哈希，不能替代 `sha256sum` 做防篡改校验。
///
/// # Examples
///
/// ```
/// use hasher_core::hash_file;
///
/// let path = std::env::temp_dir()
///     .join(format!("hasher-core-hash-file-{}.bin", std::process::id()));
/// std::fs::write(&path, b"hello rust").unwrap();
/// let h1 = hash_file(&path).unwrap();
/// let h2 = hash_file(&path).unwrap();
/// assert_eq!(h1, h2, "同一文件两次哈希必须相同");
/// let _ = std::fs::remove_file(&path);
/// ```
///
/// # Errors
///
/// 文件打不开（不存在、无权限）或读取中途出错时返回 [`io::Error`]。
pub fn hash_file(path: &Path) -> io::Result<u64> {
    let mut file = fs::File::open(path)?;
    let mut hasher = DefaultHasher::new();
    let mut buf = [0_u8; 8192];
    loop {
        let n = file.read(&mut buf)?;
        if n == 0 {
            break;
        }
        buf[..n].hash(&mut hasher);
    }
    Ok(hasher.finish())
}

/// 生成测试文件：每个文件 `file_bytes` 字节，内容由文件编号做种子、
/// 用 xorshift 生成的确定性伪随机字节——每次运行内容相同，哈希可复现。
///
/// 目录不存在时会自动创建。返回按编号排序的全部文件路径。
///
/// # Examples
///
/// ```
/// use hasher_core::make_test_files;
///
/// let dir = std::env::temp_dir()
///     .join(format!("hasher-core-make-files-{}", std::process::id()));
/// let paths = make_test_files(&dir, 2, 1024).unwrap();
/// assert_eq!(paths.len(), 2);
/// assert!(paths[0].is_file());
/// std::fs::remove_dir_all(&dir).unwrap();
/// ```
///
/// # Errors
///
/// 目录创建失败或任一文件写不进去时返回 [`io::Error`]。
pub fn make_test_files(dir: &Path, n_files: usize, file_bytes: usize) -> io::Result<Vec<PathBuf>> {
    fs::create_dir_all(dir)?;
    let mut paths = Vec::with_capacity(n_files);
    for i in 0..n_files {
        let path = dir.join(format!("file-{i:03}.bin"));
        let mut data = Vec::with_capacity(file_bytes);
        let mut x: u64 = 0x9E37_79B9_7F4A_7C15u64.wrapping_add(i as u64);
        while data.len() < file_bytes {
            x ^= x << 13;
            x ^= x >> 7;
            x ^= x << 17;
            data.extend_from_slice(&x.to_le_bytes());
        }
        data.truncate(file_bytes);
        fs::write(&path, &data)?;
        paths.push(path);
    }
    Ok(paths)
}

/// 单线程版：顺序算每个文件的哈希。
///
/// 返回 `(路径，哈希值)` 列表，顺序与输入 `paths` 相同。
/// 它是多线程版的"正确答案"：两个版本的结果按路径排序后必须逐项相等。
///
/// # Examples
///
/// ```
/// use hasher_core::{hash_single_thread, make_test_files};
///
/// let dir = std::env::temp_dir()
///     .join(format!("hasher-core-single-{}", std::process::id()));
/// let paths = make_test_files(&dir, 3, 1024).unwrap();
/// let out = hash_single_thread(&paths).unwrap();
/// assert_eq!(out.len(), 3);
/// std::fs::remove_dir_all(&dir).unwrap();
/// ```
///
/// # Errors
///
/// 任一文件算哈希失败时返回该文件的 [`io::Error`]，已算出的结果丢弃。
pub fn hash_single_thread(paths: &[PathBuf]) -> io::Result<Vec<(PathBuf, u64)>> {
    let mut out = Vec::with_capacity(paths.len());
    for p in paths {
        out.push((p.clone(), hash_file(p)?));
    }
    Ok(out)
}

/// 多线程版：任务 channel 分发路径，结果 channel 回传哈希。
///
/// 主线程经任务 channel 把文件路径发给 `n_workers` 个 worker，
/// 每个 worker 读文件、算哈希，再经结果 channel 把结果发回主线程聚合。
/// mpsc 的 `Receiver` 只有一份、不能 clone，所以用 `Arc<Mutex<Receiver>>`
/// 让多个 worker 轮流取任务——这是标准库里实现"多消费者"的标准写法，
/// 代价是取任务时要抢一把小锁；真正的多消费者 channel 在 crossbeam 里。
///
/// 返回结果的顺序不固定（哪个 worker 先算完、哪个结果先到），
/// 调用方需要按路径排序后再与单线程版比对。
///
/// # Examples
///
/// ```
/// use hasher_core::{hash_multi_thread, hash_single_thread, make_test_files};
///
/// let dir = std::env::temp_dir()
///     .join(format!("hasher-core-multi-{}", std::process::id()));
/// let paths = make_test_files(&dir, 4, 1024).unwrap();
/// let mut multi = hash_multi_thread(&paths, 2).unwrap();
/// let mut single = hash_single_thread(&paths).unwrap();
/// multi.sort();
/// single.sort();
/// assert_eq!(multi, single);
/// std::fs::remove_dir_all(&dir).unwrap();
/// ```
///
/// # Errors
///
/// 任一文件算哈希失败时返回该文件的 [`io::Error`]，
/// 其余已收到的结果丢弃。
pub fn hash_multi_thread(paths: &[PathBuf], n_workers: usize) -> io::Result<Vec<(PathBuf, u64)>> {
    let (task_tx, task_rx) = mpsc::channel::<PathBuf>();
    let (result_tx, result_rx) = mpsc::channel::<(PathBuf, io::Result<u64>)>();
    let task_rx = Arc::new(Mutex::new(task_rx));

    let mut handles = Vec::with_capacity(n_workers);
    for _ in 0..n_workers {
        let task_rx = Arc::clone(&task_rx);
        let result_tx = result_tx.clone();
        handles.push(thread::spawn(move || {
            loop {
                let task = {
                    let rx = task_rx.lock().unwrap();
                    rx.recv()
                };
                match task {
                    Ok(path) => {
                        let r = hash_file(&path);
                        // 接收端若已关闭，send 失败也无所谓：直接丢掉，不 panic。
                        let _ = result_tx.send((path, r));
                    }
                    Err(_) => break, // 任务 channel 关闭：没有更多任务，退出。
                }
            }
        }));
    }
    drop(result_tx); // 主线程这份 result_tx 也要丢掉，否则结果收不完。

    for p in paths {
        task_tx.send(p.clone()).unwrap();
    }
    drop(task_tx); // 发完任务就关闭 channel：worker 取完任务就退出。

    let mut out = Vec::with_capacity(paths.len());
    for (path, r) in result_rx {
        out.push((path, r?));
    }
    for h in handles {
        h.join().unwrap();
    }
    Ok(out)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn tmp_dir(name: &str) -> PathBuf {
        std::env::temp_dir().join(format!("hasher-core-test-{name}"))
    }

    #[test]
    fn hash_is_deterministic() {
        let dir = tmp_dir("deterministic");
        let _ = fs::remove_dir_all(&dir);
        let paths = make_test_files(&dir, 3, 4096).unwrap();
        let h1 = hash_file(&paths[0]).unwrap();
        let h2 = hash_file(&paths[0]).unwrap();
        assert_eq!(h1, h2, "同一文件两次哈希必须相同");
        assert_ne!(h1, hash_file(&paths[1]).unwrap(), "不同文件哈希应不同");
        fs::remove_dir_all(&dir).unwrap();
    }

    #[test]
    fn empty_file_hashes_without_error() {
        let dir = tmp_dir("empty");
        let _ = fs::remove_dir_all(&dir);
        fs::create_dir_all(&dir).unwrap();
        let empty = dir.join("empty.bin");
        fs::write(&empty, []).unwrap();
        assert!(hash_file(&empty).is_ok());
        fs::remove_dir_all(&dir).unwrap();
    }

    #[test]
    fn single_and_multi_thread_agree() {
        let dir = tmp_dir("agree");
        let _ = fs::remove_dir_all(&dir);
        let paths = make_test_files(&dir, 12, 8192).unwrap();
        let mut single = hash_single_thread(&paths).unwrap();
        let mut multi = hash_multi_thread(&paths, 4).unwrap();
        single.sort();
        multi.sort();
        assert_eq!(single, multi);
        fs::remove_dir_all(&dir).unwrap();
    }

    #[test]
    fn more_workers_than_files_still_works() {
        let dir = tmp_dir("many-workers");
        let _ = fs::remove_dir_all(&dir);
        let paths = make_test_files(&dir, 2, 4096).unwrap();
        let mut out = hash_multi_thread(&paths, 8).unwrap();
        assert_eq!(out.len(), 2);
        out.sort();
        let mut single = hash_single_thread(&paths).unwrap();
        single.sort();
        assert_eq!(out, single);
        fs::remove_dir_all(&dir).unwrap();
    }

    #[test]
    fn missing_file_returns_error() {
        let missing = PathBuf::from("/tmp/hasher-core-no-such-file.bin");
        assert!(hash_file(&missing).is_err());
        let paths = vec![missing];
        assert!(hash_single_thread(&paths).is_err());
    }
}

//! hasher-cli：项目 2 文件哈希器的命令行入口。
//!
//! 只做三件"编排"的事：解析命令行参数、调用 `hasher-core` 的库函数、
//! 打印计时与加速比。哈希算法、线程池、channel 流水线都在 lib 里，
//! 这个 bin 里没有任何业务逻辑——这是 lib + bin 分离的要点。

use hasher_core::{hash_multi_thread, hash_single_thread, make_test_files};
use std::fs;
use std::io;
use std::path::{Path, PathBuf};
use std::thread;
use std::time::Instant;

/// 递归收集目录下所有文件的路径（不跟随符号链接，不含目录本身）。
fn collect_files(dir: &Path, out: &mut Vec<PathBuf>) -> io::Result<()> {
    for entry in fs::read_dir(dir)? {
        let path = entry?.path();
        if path.is_dir() {
            collect_files(&path, out)?;
        } else if path.is_file() {
            out.push(path);
        }
    }
    Ok(())
}

/// 用法：`hasher-cli [目录] [worker 数]`。
/// 不给目录时，生成 64 个 1 MiB 测试文件跑基准对比；
/// 给目录时，递归扫描该目录下的全部文件。
fn main() -> io::Result<()> {
    let args: Vec<String> = std::env::args().skip(1).collect();
    let n_workers = args
        .get(1)
        .and_then(|s| s.parse::<usize>().ok())
        .unwrap_or_else(|| {
            thread::available_parallelism()
                .map(|n| n.get())
                .unwrap_or(4)
        });
    println!("本机可用并行度：{n_workers} 个线程");

    // 模式一：扫描真实目录；模式二：生成测试文件跑基准对比。
    let (paths, generated_dir) = match args.first() {
        Some(dir) => {
            let mut files = Vec::new();
            collect_files(Path::new(dir), &mut files)?;
            files.sort();
            println!("扫描目录 {dir}，共 {} 个文件", files.len());
            (files, None)
        }
        None => {
            let dir = std::env::temp_dir().join("hasher-ws-bench");
            let n_files = 64;
            let file_bytes = 1024 * 1024;
            let paths = make_test_files(&dir, n_files, file_bytes)?;
            println!("已生成 {n_files} 个测试文件，每个 {file_bytes} 字节");
            (paths, Some(dir))
        }
    };
    if paths.is_empty() {
        println!("没有文件可哈希，退出。");
        return Ok(());
    }

    let t0 = Instant::now();
    let single = hash_single_thread(&paths)?;
    let single_elapsed = t0.elapsed();

    let t0 = Instant::now();
    let mut multi = hash_multi_thread(&paths, n_workers)?;
    let multi_elapsed = t0.elapsed();

    // 结果必须一致：按路径排序后逐项比较，顺序不同不算错。
    let mut single_sorted = single.clone();
    single_sorted.sort();
    multi.sort();
    assert_eq!(single_sorted, multi, "单线程与多线程的哈希结果必须一致");

    println!("单线程：{single_elapsed:?}，多线程（{n_workers} worker）：{multi_elapsed:?}");
    let speedup = single_elapsed.as_secs_f64() / multi_elapsed.as_secs_f64();
    println!("加速比：{speedup:.2}x");
    println!(
        "示例：{} -> {:#018x}",
        single_sorted[0].0.display(),
        single_sorted[0].1
    );

    if let Some(dir) = generated_dir {
        fs::remove_dir_all(&dir)?; // 清理测试数据。
    }
    Ok(())
}

use sha2::{Digest, Sha256};
use std::fs;
use std::io::{self, Read};
use std::path::Path;

/// 对单个文件算 SHA-256，返回小写十六进制字符串（与 sha256sum 输出一致）。
pub fn hash_file_sha256(path: &Path) -> io::Result<String> {
    let mut file = fs::File::open(path)?;
    let mut hasher = Sha256::new();
    let mut buf = [0_u8; 8192];
    loop {
        let n = file.read(&mut buf)?;
        if n == 0 {
            break;
        }
        hasher.update(&buf[..n]);
    }
    Ok(hasher
        .finalize()
        .iter()
        .map(|b| format!("{b:02x}"))
        .collect())
}

//! 第 28 天 · 第四周复盘验收：模块、文档、测试、特性四件套一次串起来。
//!
//! 一个小库演示第 4 周的全部工程化机制：
//! - 模块与可见性（`pub` / `pub(crate)` / 私有）
//! - 文档注释 `///` 与会被执行的 doctest
//! - 单元测试 `#[cfg(test)]`
//! - 特性开关 `fast`（`[features]`，零依赖）
//!
//! # Examples
//!
//! ```
//! assert_eq!(rust_day28::count_words("hello rust world"), 3);
//! ```

#![warn(missing_docs)]

use std::collections::HashMap;

/// 把文本按空白切成词，返回词的个数。
///
/// 空白包括空格、制表符与换行；首尾与连续空白不产生空词。
/// 实现就是 `split_whitespace` 的计数——第 22 天的教训：
/// 写函数之前，先想清楚"它该属于哪个模块"。
///
/// # Examples
///
/// ```
/// assert_eq!(rust_day28::count_words("hello rust world"), 3);
/// assert_eq!(rust_day28::count_words("  hello   rust  "), 2);
/// assert_eq!(rust_day28::count_words(""), 0);
/// ```
pub fn count_words(text: &str) -> usize {
    words::split(text).count()
}

/// 统计词频，返回出现次数最多的前 `n` 个词。
///
/// 返回 `(词，次数)` 列表，按次数降序排列；次数相同时按词的字典序排列，
/// 保证输出是确定性的——基准测试（第 24 天）最忌讳"每次跑结果顺序都不同"。
///
/// # Examples
///
/// ```
/// let top = rust_day28::top_words("a b a c b a", 2);
/// assert_eq!(top, vec![("a".to_string(), 3), ("b".to_string(), 2)]);
/// ```
pub fn top_words(text: &str, n: usize) -> Vec<(String, usize)> {
    let mut freq: HashMap<&str, usize> = HashMap::new();
    for w in words::split(text) {
        *freq.entry(w).or_insert(0) += 1;
    }
    let mut items: Vec<(String, usize)> =
        freq.into_iter().map(|(w, c)| (w.to_string(), c)).collect();
    items.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    items.truncate(n);
    items
}

/// 统计文本里"词内字符"（字母或数字）的个数。
///
/// 标点与空白不算。顺带演示 `pub(crate)` 函数的合法用法：
/// 它只在本 crate 内可见，但本 crate 的公开函数可以调它——
/// 这就是"对内开放、对外封闭"的接口（第 22 天）。
///
/// # Examples
///
/// ```
/// assert_eq!(rust_day28::count_word_chars("hello, rust!"), 9);
/// ```
pub fn count_word_chars(text: &str) -> usize {
    text.chars().filter(|&c| words::is_word_char(c)).count()
}

/// 特性开关演示：只有开启 `fast` 特性才编译。
///
/// 它和 `count_words` 算的是同一个数，区别只是实现走了一条"快路径"：
/// 这里只是演示 `#[cfg(feature = ...)]` 的开关机制，
/// 真实项目里这种开关后面挂的是可选依赖或另一套实现（第 25 天）。
///
/// 跑 `cargo test` 时这个函数不存在；跑 `cargo test --features fast` 时才有。
#[cfg(feature = "fast")]
pub fn count_words_fast(text: &str) -> usize {
    text.split_whitespace().count()
}

/// 模块与可见性：第 22 天的三个档位都在这里。
///
/// - `words` 本身是 `pub`：外部能 `use rust_day28::words`。
/// - `split` 是 `pub`：模块的公开 API。
/// - `is_word_char` 是 `pub(crate)`：只在本 crate 内可见，
///   外部 `use` 会报 E0603。
/// - `normalize` 是私有的：只有本模块内能调。
pub mod words {
    /// 把文本按空白切成词，返回迭代器。
    pub fn split(text: &str) -> impl Iterator<Item = &str> {
        text.split_whitespace()
    }

    /// 判断一个字符是不是"词内字符"（字母或数字）。
    ///
    /// 只在本 crate 内可见：外部 crate 调它会报 `E0603`。
    pub(crate) fn is_word_char(c: char) -> bool {
        c.is_alphanumeric()
    }

    /// 私有辅助：把词转成小写做归一化。
    fn normalize(word: &str) -> String {
        word.to_lowercase()
    }

    /// 归一化后的切词：内部演示私有函数怎么被公开函数调用。
    pub fn split_normalized(text: &str) -> Vec<String> {
        split(text).map(normalize).collect()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn count_words_basic() {
        assert_eq!(count_words("hello rust world"), 3);
        assert_eq!(count_words("  hello   rust  "), 2);
        assert_eq!(count_words(""), 0);
    }

    #[test]
    fn top_words_is_deterministic() {
        let top = top_words("a b a c b a", 2);
        assert_eq!(top, vec![("a".to_string(), 3), ("b".to_string(), 2)]);
        assert_eq!(top_words("x", 5).len(), 1);
    }

    #[test]
    fn words_module_is_public() {
        assert_eq!(words::split("one two").count(), 2);
        assert!(words::is_word_char('r'));
        assert!(!words::is_word_char(' '));
        assert_eq!(words::split_normalized("Hello RUST"), vec!["hello", "rust"]);
    }

    #[test]
    #[cfg(feature = "fast")]
    fn fast_feature_counts_the_same() {
        assert_eq!(count_words_fast("hello rust world"), 3);
        assert_eq!(
            count_words_fast("hello rust world"),
            count_words("hello rust world")
        );
    }
}

//! 第 29 天 · async/await 与 Future：为什么需要异步。
//!
//! 四个现象一次看清：
//! 1. Future 是惰性的：async fn 调用只造出 Future，不执行；
//! 2. `.await` 不阻塞线程：两个 300ms 睡眠可以同时等；
//! 3. 阻塞调用会拖住整个 runtime（current_thread 下最明显）；
//! 4. 阻塞操作要交给 `spawn_blocking`。
//!
//! 运行：`cargo run`（tokio 1.x，features = ["full"]）。

use std::sync::atomic::{AtomicUsize, Ordering};
use std::time::{Duration, Instant};

use tokio::time::sleep;

static STARTED: AtomicUsize = AtomicUsize::new(0);

async fn greet(name: &str) {
    STARTED.fetch_add(1, Ordering::SeqCst);
    println!("你好，{name}！");
}

#[tokio::main(flavor = "current_thread")]
async fn main() {
    // ---- 1. Future 是惰性的 ----
    let fut = greet("Rust");
    println!(
        "创建 Future 后，STARTED = {}",
        STARTED.load(Ordering::SeqCst)
    );
    fut.await;
    println!("await 之后，STARTED = {}", STARTED.load(Ordering::SeqCst));

    // ---- 2. .await 不阻塞线程：两个睡眠同时等 ----
    let start = Instant::now();
    let ((), ()) = tokio::join!(
        sleep(Duration::from_millis(300)),
        sleep(Duration::from_millis(300)),
    );
    let joined = start.elapsed().as_millis();
    println!("两个 300ms 睡眠 join! 用时：{joined}ms（顺序等要 600ms）");
    assert!(joined < 550, "并发等待应该远小于 600ms");

    // ---- 3. 阻塞调用拖住 runtime ----
    let start = Instant::now();
    let handle = tokio::spawn(async move {
        sleep(Duration::from_millis(100)).await;
        start.elapsed().as_millis()
    });
    std::thread::sleep(Duration::from_millis(500));
    let b_ms = handle.await.unwrap();
    println!("任务 B 在 {b_ms}ms 完成（本该 100ms，却被阻塞调用拖到 500ms 之后）");
    assert!(b_ms >= 500, "阻塞调用应该拖住任务 B");

    // ---- 4. 正确做法：spawn_blocking ----
    let start = Instant::now();
    let handle = tokio::spawn(async move {
        sleep(Duration::from_millis(100)).await;
        start.elapsed().as_millis()
    });
    tokio::task::spawn_blocking(|| std::thread::sleep(Duration::from_millis(500)))
        .await
        .unwrap();
    let b_ms = handle.await.unwrap();
    println!("任务 B 在 {b_ms}ms 完成（阻塞调用进了阻塞线程池，互不干扰）");
    assert!(b_ms < 400, "spawn_blocking 不应拖住任务 B");
}
